/* https://unpkg.com/lenis@1.3.23/dist/lenis.css */
html.lenis,
html.lenis body {
  height: auto;
}

.lenis:not(.lenis-autoToggle).lenis-stopped {
  overflow: clip;
}

.lenis [data-lenis-prevent],
.lenis [data-lenis-prevent-wheel],
.lenis [data-lenis-prevent-touch],
.lenis [data-lenis-prevent-vertical],
.lenis [data-lenis-prevent-horizontal] {
  overscroll-behavior: contain;
}

.lenis.lenis-smooth iframe {
  pointer-events: none;
}

.lenis.lenis-autoToggle {
  transition-property: overflow;
  transition-duration: 1ms;
  transition-behavior: allow-discrete;
}


/* website-extractor: hide Framer editor-bar iframe */
#__framer-editorbar { display: none !important; }

/* website-extractor: hide runtime-injected Framer badge */
#__framer-badge-container, .__framer-badge, [data-framer-badge], a[href*="framer.com"][class*="badge"] { display: none !important; }

/* Tool orbit: one composed ring preserves the original radial layout. */
.tool-orbit-section .framer-a2joq5 {
  width: 800px !important;
  height: 800px !important;
}

.tool-orbit-section .framer-a2joq5 > [data-framer-name^="Arm"],
.tool-orbit-section .framer-1gtf5l4 {
  display: none !important;
}

.tool-orbit-section .framer-aw1y8w { z-index: 2; }

.tool-orbit-ring {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  animation: tool-orbit 32s linear infinite;
}

.tool-orbit-icon {
  position: absolute;
  display: grid;
  place-items: center;
  width: 72px;
  height: 72px;
  transform: translate(-50%, -50%);
}

.tool-orbit-card {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  padding: clamp(8px, 1.2vw, 12px);
  background: rgba(255, 255, 255, .92);
  border: 1px solid rgba(17, 17, 17, .08);
  border-radius: 16px;
  box-shadow: 0 12px 28px rgba(17, 17, 17, .12);
  animation: tool-orbit 32s linear infinite reverse;
}

.tool-orbit-card img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

@keyframes tool-orbit {
  to { rotate: 1turn; }
}

@media (prefers-reduced-motion: reduce) {
  .tool-orbit-ring,
  .tool-orbit-card { animation: none; }
}

